{
  "declined": "none",
  "criteria": [
    {
      "id": "task",
      "score": 4,
      "reason": "文章回答題目並給出理由和立場，如 \"I believe all restaurants should follow this rule.\"，但沒有討論反對者觀點的更多細節或反駁深度。"
    },
    {
      "id": "organization",
      "score": 4,
      "reason": "文章有清楚段落分段（引言、兩個理由、反駁與結論），且使用連接詞如 \"First,\" 和 \"Second,\"，結構清晰。"
    },
    {
      "id": "vocabulary",
      "score": 3,
      "reason": "詞彙能表達意思（如 \"plastic straws\", \"save money\"），但有拼寫錯誤和少量用詞不精確（例如 \"enviroment\", \"recieve\"）。"
    },
    {
      "id": "grammar",
      "score": 3,
      "reason": "大部分句子正確且可理解，但有動詞拼寫錯誤與少數語法小錯誤（例如 \"is very bad for the enviroment\" 可更正為 \"is very bad for the environment\"）。"
    }
  ],
  "issues": [
    {
      "quote": "enviroment",
      "type": "spelling",
      "why": "此字拼寫錯誤，應為常見單字 \"environment\"，拼錯會影響正式寫作的分數。",
      "suggestion": "environment"
    },
    {
      "quote": "recieve",
      "type": "spelling",
      "why": "此字拼寫錯誤，正確拼法為 \"receive\"（i before e 規則），寫錯會讓文章顯得不夠仔細。",
      "suggestion": "receive"
    },
    {
      "quote": "I definately support stopping free plastic straws and utensils.",
      "type": "spelling",
      "why": "單字 \"definately\" 拼寫錯誤，正確為 \"definitely\"；此外句子可更自然表達為支持停止免費提供塑膠用品。",
      "suggestion": "I definitely support stopping free plastic straws and utensils."
    }
  ],
  "more": [
    {
      "quote": "plastic is very bad for the enviroment.",
      "type": "grammar",
      "why": "句首應大寫（Plastic），且可改為更精確的說法，如 the environment is harmed by plastic waste。",
      "suggestion": "Plastic is very bad for the environment."
    },
    {
      "quote": "they sometimes recieve a small discount for bringing their own cup, so it also saves money.",
      "type": "cohesion",
      "why": "這句包含兩個想法（折扣與省錢），連接詞使用正確但可更流暢；主詞單複數一致也可改善（it → they）。",
      "suggestion": "They sometimes receive a small discount for bringing their own cup, so they also save money."
    },
    {
      "quote": "Most plastic straws and forks are used for only a few minutes, but they stay in the ocean for hundreds of years.",
      "type": "word-choice",
      "why": "用詞清楚，但可以改用更自然的搭配，如 \"single-use\" 描述一次性用品會更地道。",
      "suggestion": "Most plastic straws and forks are single-use and are used for only a few minutes, but they can remain in the ocean for hundreds of years."
    },
    {
      "quote": "Some people say that this rule is inconvenient.",
      "type": "tone",
      "why": "此處語氣中性但可稍微擴展反對者理由以強化論點的說服力。",
      "suggestion": "Some people say that this rule is inconvenient because they forget to bring reusable items or need disposable options for hygiene."
    }
  ],
  "strengths": [
    {
      "quote": "I believe all restaurants should follow this rule.",
      "why": "清楚表達立場，讓讀者一開始就知道作者的觀點，論述方向明確。"
    },
    {
      "quote": "Many of my friends now carry their own metal straws and chopsticks.",
      "why": "使用具體例子支撐論點，有助於說服力並展示實際可行性。"
    }
  ],
  "summary": "你已經有明確立場並且段落結構良好，下一步請注意常見單字拼寫（例如 environment, receive, definitely）和句子小修正，還可以多擴展反對意見的細節並進一步反駁，讓論證更有深度。繼續練習拼寫與連接句子的流暢性，你會更進步。"
}
